"""Minimum Add to Make Parentheses Valid — counter instead of a stack.

`open_count` is the number of unmatched '('; every ')' with none open is itself
an insertion.

Time: O(n)   Space: O(1)
"""


class Solution:
    def minAddToMakeValid(self, s: str) -> int:
        additions = open_count = 0
        for ch in s:
            if ch == "(":
                open_count += 1
            elif open_count:
                open_count -= 1
            else:
                additions += 1
        return additions + open_count
